INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(6101, 'Judges 3:2', 'Judges', 3, 2, '&nbsp;هغۀ داسې د دې دپاره وکړل چې د بنى اِسرائيلو هر يو نسل ته د جنګ چل وښائى، خصوصاً هغوئ ته چې کومو مخکښې هيڅکله هم جنګ نۀ دے کړے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6102, 'Judges 3:3', 'Judges', 3, 3, '&nbsp;په هغه مُلک کښې پينځۀ فلستى ښارونه پاتې شول، ټول کنعانيان، صيدانيان او حِويان چې د بعل حرمون غر نه واخله د حمات درې پورې د لبنان په غرونو کښې اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6103, 'Judges 3:4', 'Judges', 3, 4, '&nbsp;هغوئ د بنى اِسرائيلو دپاره يو آزمېښت وو، چې دا معلومه شى چې مالِک خُدائ د موسىٰ په ذريعه بنى اِسرائيلو له کوم حُکمونه ورکړى وُو چې په هغې باندې عمل کوى او کۀ نه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6104, 'Judges 3:5', 'Judges', 3, 5, '&nbsp;نو داسې بنى اِسرائيل د کنعانيانو، حِتيانو، اموريانو، فرزيانو، حِويانو او يبوسيانو سره اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6105, 'Judges 3:6', 'Judges', 3, 6, '&nbsp;هغوئ د دوئ لوڼه وادۀ کړې او خپلې لوڼه يې د هغوئ زامنو له ورکړې او د هغوئ د معبودانو عبادت يې وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6106, 'Judges 3:7', 'Judges', 3, 7, '&nbsp;بنى اِسرائيلو د مالِک خُدائ خِلاف ګناه وکړه، خپل خُدائ پاک يې هېر کړو او د بعل او اشيرې د بُتانو عبادت يې وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6107, 'Judges 3:8', 'Judges', 3, 8, '&nbsp;نو مالِک خُدائ بنى اِسرائيلو ته په قهر شو او د مسوپتاميه بادشاه کوشن رِسعتيم ته يې حواله کړل او اتۀ کاله يې په هغوئ حکومت وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6108, 'Judges 3:9', 'Judges', 3, 9, '&nbsp;بيا بنى اِسرائيلو مالِک خُدائ ته فرياد وکړو او مالِک خُدائ د هغوئ د بچ کولو دپاره يو خلاصونکے ورولېږلو. دا عتنى‌اېل وو چې د کالب د کشر ورور قنز زوئ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6109, 'Judges 3:10', 'Judges', 3, 10, '&nbsp;د مالِک خُدائ روح په هغۀ نازل شو او هغه د بنى اِسرائيلو قاضى شو. عتنى‌اېل جنګ له لاړو او مالِک خُدائ هغۀ له د مسوپتاميه په بادشاه باندې فتح ورکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6110, 'Judges 3:11', 'Judges', 3, 11, '&nbsp;څلوېښت کاله په هغه مُلک کښې امن وو او بيا د قنز زوئ عتنى‌اېل مړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6111, 'Judges 3:12', 'Judges', 3, 12, '&nbsp;بنى اِسرائيلو د مالِک خُدائ خِلاف بيا ګناه وکړه، نو د دې په وجه مالِک خُدائ د موآب بادشاه عجلون د بنى اِسرائيلو نه طاقتور کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6112, 'Judges 3:13', 'Judges', 3, 13, '&nbsp;عجلون عمونيان او عماليقيان د ځان سره ملګرى کړل، هغوئ بنى اِسرائيلو له شکست ورکړو او د کجورو ښار يريحو يې قبضه کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6113, 'Judges 3:14', 'Judges', 3, 14, '&nbsp;بنى اِسرائيليان اتلس کاله د عجلون بادشاه د اختيار د لاندې وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6114, 'Judges 3:15', 'Judges', 3, 15, '&nbsp;بيا بنى اِسرائيلو مالِک خُدائ ته فرياد وکړو او مالِک خُدائ د هغوئ د بچ کولو دپاره يو خلاصونکے ورولېږلو. د هغۀ نوم اهُود وو، هغه د بنيامين د قبيلې د جيرا زوئ وو او هغه ګس مټے وو. بنى اِسرائيلو اهُود د موآب بادشاه عجلون ته د محصُول سره ورولېږلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6115, 'Judges 3:16', 'Judges', 3, 16, '&nbsp;اهُود يوه دوه مخيزه تُوره جوړه کړې وه چې تقريباً اتلس اِنچې اوږده وه. هغۀ دا د خپلو جامو لاندې د ښۍ پښې سپينې پورې تړلې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6116, 'Judges 3:17', 'Judges', 3, 17, '&nbsp;بيا هغۀ محصُول عجلون له يوړو، څوک چې ډېر څورب سړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6117, 'Judges 3:18', 'Judges', 3, 18, '&nbsp;کله چې اهُود هغۀ له محصُول ورکړو، چې کومو سړو دا راوړے وو نو هغوئ يې رُخصت کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6118, 'Judges 3:19', 'Judges', 3, 19, '&nbsp;خو چې کله اهُود د کاڼو بُتانو ته ورسېدو چې جِلجال ته نزدې وو، نو عجلون ته راواپس شو او ورته يې ووئيل، ”بادشاه سلامت، زما سره ستا دپاره يو د راز خبره ده.“ نو بادشاه ورته ووئيل، ”اوس خبره مۀ کوه.“ او د هغۀ ټول نوکران د هغۀ د حضور نه لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6119, 'Judges 3:20', 'Judges', 3, 20, '&nbsp;بيا چې کله بادشاه په چت باندې په خپله يخه کوټه کښې ناست وو، اهُود هغۀ له ورَغلو او ورته يې ووئيل، ”زما سره ستا دپاره د خُدائ پاک نه يو پېغام دے.“ نو بادشاه د تخت نه پاڅېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6120, 'Judges 3:21', 'Judges', 3, 21, '&nbsp;اهُود د خپل ګس لاس سره د ښى طرف نه تُوره راوويسته او د بادشاه په خېټه کښې يې ننه ويستله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6121, 'Judges 3:22', 'Judges', 3, 22, '&nbsp;تُوره دومره ډُوبه لاړه چې د دې لاسکے په وازګه باندې پټ شو. اهُود تُوره د بادشاه د خېټې نه راونۀ ويستله او د بادشاه کولمو نه ګند راووتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6122, 'Judges 3:23', 'Judges', 3, 23, '&nbsp;بيا اهُود برنډې ته ووتلو، هغۀ پسې يې دروازې بندې کړې او تالې يې ولګولې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6123, 'Judges 3:24', 'Judges', 3, 24, '&nbsp;او ترې نه لاړو. نوکران راغلل او وې ليدل چې دروازې تاله وې، هغوئ صِرف دا خيال کولو چې بادشاه دننه دے او متيازې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6124, 'Judges 3:25', 'Judges', 3, 25, '&nbsp;هغوئ تر څۀ وخته پورې انتظار وکړو، خو چې هغۀ بيا هم دروازه کولاو نۀ کړه، نو هغوئ چابى واخستله او دا يې کولاو کړه. او د هغوئ نېک دننه په فرش باندې مړ پروت وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6125, 'Judges 3:26', 'Judges', 3, 26, '&nbsp;په کوم وخت چې هغوئ اِنتظار کولو نو اهُود وتښتېدو، هغه د کاڼو بُتانو نه تېر شو او سعيرت ته وتښتېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6126, 'Judges 3:27', 'Judges', 3, 27, '&nbsp;کله چې هغه د غرونو مُلک اِفرائيم ته ورسېدو، نو هغۀ بيګل وغږولو چې بنى اِسرائيليان د جنګ دپاره راغونډ کړى، بيا يې هغوئ د غر نه لاندې بوتلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6127, 'Judges 3:28', 'Judges', 3, 28, '&nbsp;هغۀ ورته ووئيل، ”په ما پسې راځئ. مالِک خُدائ تاسو له په خپلو دشمنانو يعنې موآبيانو باندې فتح درکړې ده.“ نو هغوئ په اهُود پسې لاندې لاړل او هغه ځائ يې قبضه کړو چې په کوم ځائ کښې به موآبيان د اُردن سيند نه پورې وتل، هغوئ هيچا له هم د پورې وتلو اجازت ورنۀ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6128, 'Judges 3:29', 'Judges', 3, 29, '&nbsp;هغوئ په هغه ورځ باندې تقريباً لس زره ښۀ، تکړه موآبيان فوجيان ووژل، يو هم ونۀ تښتېدلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6129, 'Judges 3:30', 'Judges', 3, 30, '&nbsp;په هغه ورځ بنى اِسرائيلو موآبيانو له شکست ورکړو او اتيا کاله په هغه مُلک کښې امن وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6130, 'Judges 3:31', 'Judges', 3, 31, '&nbsp;ورپسې مشر د عنات زوئ شمجر وو. هغۀ شپږ سوه فلستيان په تېرۀ لښته باندې ووژل او بنى اِسرائيليان يې هم بچ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6131, 'Judges 4:1', 'Judges', 4, 1, '&nbsp;د اهُود د مرګ نه پس، بنى اِسرائيلو بيا د مالِک خُدائ خِلاف ګناه وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6132, 'Judges 4:2', 'Judges', 4, 2, '&nbsp;نو مالِک خُدائ هغوئ يو کنعانى بادشاه يابين ته حواله کړل، چا چې د حصور په ښار کښې بادشاهى کوله. د هغۀ د لښکر مشر سِسيرا وو، کوم چې په حروست هګوئيم کښې اوسېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6133, 'Judges 4:3', 'Judges', 4, 3, '&nbsp;د يابين نهۀ سوه د اوسپنې ګاډۍ وې او هغۀ د ظلم زياتى سره شل کاله په بنى اِسرائيلو حکومت وکړو. بيا بنى اِسرائيلو د مدد دپاره مالِک خُدائ ته فرياد وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6134, 'Judges 4:4', 'Judges', 4, 4, '&nbsp;نو د لفيدوت ښځه، دبوره يوه پېغمبره وه او په هغه وخت کښې هغې د يو قاضى په توګه د بنى اِسرائيلو خِدمت کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6135, 'Judges 4:5', 'Judges', 4, 5, '&nbsp;هغه به د اِفرائيم غرونو په مُلک کښې د راما او بيت‌ايل په مينځ کښې د کجورې يوې خاص ونې لاندې کښېناسته او بنى اِسرائيل به هلته د فېصلو کولو دپاره ورتلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6136, 'Judges 4:6', 'Judges', 4, 6, '&nbsp;يوه ورځ هغې په نفتالى کښې د قادِس ښار د ابى‌نوعم زوئ برق راوغوښتلو او ورته يې وفرمائيل، ”مالِک خُدائ، د بنى اِسرائيلو خُدائ پاک تا له دا حُکم درکړے دے چې د نفتالى او زبولون قبيلو نه لس زره سړى روان کړه او د تبور غر ته يې بوځه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6137, 'Judges 4:7', 'Judges', 4, 7, '&nbsp;زۀ به د يابين د لښکر مشر سِسيرا وغولوم چې د قيسون سيند سره ستا خِلاف جنګ وکړى. د هغۀ سره به خپلې ګاډۍ او فوجيان وى، خو زۀ به تا له په هغۀ باندې فتح درکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6138, 'Judges 4:8', 'Judges', 4, 8, '&nbsp;برق جواب ورکړو، ”کۀ تۀ ما سره ځې نو زۀ به لاړ شم، خو کۀ تۀ راسره نۀ ځې، نو بيا زۀ هم نۀ ځم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6139, 'Judges 4:9', 'Judges', 4, 9, '&nbsp;هغې جواب ورکړو، ”ټيک ده، زۀ به تا سره لاړه شم، خو په دې منصوبه کښې به تا ته عزت نۀ ملاويږى، ځکه چې مالِک خُدائ به سِسيرا يوې ښځې ته حواله کړى.“ نو دبوره د برق سره قادِس ته روانه شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6140, 'Judges 4:10', 'Judges', 4, 10, '&nbsp;برق د زبولون او نفتالى قبيلې قادِس ته راوغوښتلې او لس زره سړى په هغۀ پسې روان وُو. دبوره د هغۀ سره لاړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6141, 'Judges 4:11', 'Judges', 4, 11, '&nbsp;په دې دوران کښې قينى حِبر په ضعننيم کښې د څېړۍ ونې سره نزدې د قادِس سره خپله خېمه لګولې وه. هغه د نورو قينيانو نه لرې تلے وو، چې هغوئ د موسىٰ د اوخى حوباب اولاد وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6142, 'Judges 4:12', 'Judges', 4, 12, '&nbsp;کله چې سِسيرا خبر شو چې برق د تبور غرونو ته ختلے دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6143, 'Judges 4:13', 'Judges', 4, 13, '&nbsp;نو هغۀ خپلې نهۀ سوه د اوسپنې ګاډۍ او ټول سړى راوغوښتل او هغوئ يې د حروست هګوئيم نه د قيسون سيند ته ولېږل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6144, 'Judges 4:14', 'Judges', 4, 14, '&nbsp;دبورې برق ته ووئيل، ”لاړ شه. مالِک خُدائ به ستا لارښودنه کوى، نن هغۀ تا له په سِسيرا باندې فتح درکړې ده.“ نو برق د خپلو لسو زرو سړو سره د تبور غر نه راکوز شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6145, 'Judges 4:15', 'Judges', 4, 15, '&nbsp;کله چې برق او د هغۀ لښکر حمله وکړه، نو مالِک خُدائ سِسيرا د خپلو ټولو جنګى ګاډو او سړو سره په وارخطايۍ آخته کړل. سِسيرا د خپلې ګاډۍ نه راټوپ کړل او پېدل وتښتېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6146, 'Judges 4:16', 'Judges', 4, 16, '&nbsp;برق تر حروست هګوئيم پورې په ګاډو او لښکر پسې وو او د سِسيرا ټول لښکر ووژلے شو. يو سړے هم پاتې نۀ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6147, 'Judges 4:17', 'Judges', 4, 17, '&nbsp;سِسيرا د قينى حِبر ښځې ياعيل خېمې ته وتښتېدو، ځکه چې د حصور بادشاه يابين د حِبر د خاندان سره د امن تړون وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6148, 'Judges 4:18', 'Judges', 4, 18, '&nbsp;ياعيل د سِسيرا سره مِلاوېدو دپاره راووتله او ورته يې ووئيل، ”صاحِبه، دننه راشه، زما خېمې ته دننه راشه. مۀ يرېږه.“ نو هغه دننه راغلو او هغه يې په بستره کښې پټ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6149, 'Judges 4:19', 'Judges', 4, 19, '&nbsp;هغۀ هغې ته ووئيل، ”زۀ تږے يم، ما له لږې اوبۀ راکړه.“ نو هغې د پيو مشکيزه کولاو کړه، پئ يې په هغۀ وڅښل او بيا يې پټ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6150, 'Judges 4:20', 'Judges', 4, 20, '&nbsp;بيا هغۀ ورته ووئيل، ”د خېمې د دروازې په خولۀ کښې ودرېږه، چې څوک راځى او تپوس کوى چې دلته څوک شته، نو ورته وايه چې نشته.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6151, 'Judges 4:21', 'Judges', 4, 21, '&nbsp;سِسيرا ډېر ستړے وو او په خوږ خوب اودۀ شو. نو ياعيل څټک او د خېمې موږے واخستلو، غلې شان هغۀ له ورغله، هغې ورله موږے د تندى نه پورې غاړه وويستلو او موږے په زمکه کښې هم ښخ شو او هغه مړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6152, 'Judges 4:22', 'Judges', 4, 22, '&nbsp;کله چې برق په سِسيرا پسې وو نو ياعيل مِلاوېدو دپاره ورووتله او ورته يې ووئيل، ”دلته راشه. زۀ به تا ته هغه سړے وښايم چې تۀ يې ګورې.“ نو هغه د هغې سره دننه لاړو او سِسيرا هلته په زمکه مړ پروت وو چې په تندى کښې يې د خېمې موږے ټک وهلے شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6153, 'Judges 4:23', 'Judges', 4, 23, '&nbsp;په هغه ورځ خُدائ پاک بنى اِسرائيلو له په کنعانى بادشاه يابين باندې فتح ورکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6154, 'Judges 4:24', 'Judges', 4, 24, '&nbsp;بنى اِسرائيل په هغۀ باندې دومره زورَور شول چې تباه يې کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6155, 'Judges 5:1', 'Judges', 5, 1, '&nbsp;په هغه ورځ دبورې او د ابى‌نوعم زوئ برق دا حمد ووئيلو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6156, 'Judges 5:2', 'Judges', 5, 2, '&nbsp;”د مالِک خُدائ ثناء دې وى. مشرانو د بنى اِسرائيلو لارښودنه وکړه، او خلقو په خوشحالۍ سره ځانونه پېش کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6157, 'Judges 5:3', 'Judges', 5, 3, '&nbsp;واورئ اے بادشاهانو، حکومت کوونکو غوږ ونيسئ. زۀ به د مالِک خُدائ ثناء صِفت وکړم او ساز به وغږوم هغه مالِک خُدائ ته چې د بنى اِسرائيلو خُدائ پاک دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6158, 'Judges 5:4', 'Judges', 5, 4, '&nbsp;مالِکه خُدايه، کله چې تۀ د سعير د غرونو نه لاړې، کله چې تۀ د ادوم د علاقې نه راووتلې، زمکه ولړزېدله او د آسمان نه باران وورېدلو. آو، اوبۀ د وريځو نه راتوې شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6159, 'Judges 5:5', 'Judges', 5, 5, '&nbsp;د سينا مالِک خُدائ په وړاندې غرونه ولړزېدل، د مالِک خُدائ په وړاندې چې د بنى اِسرائيلو خُدائ پاک دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6160, 'Judges 5:6', 'Judges', 5, 6, '&nbsp;د عنات زوئ شمجر په وخت کښې، د ياعيل په وخت کښې، قافلې په زمکه کښې نورې نۀ تلې، او مسافر په تاو راتاو لارو باندې تلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6161, 'Judges 5:7', 'Judges', 5, 7, '&nbsp;د بنى اِسرائيلو کلى پرېښودلے شول، او دا خالى پاتې شول تر دې پورې چې دبوره د بنى اِسرائيلو د مور په شان راپېدا شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6162, 'Judges 5:8', 'Judges', 5, 8, '&nbsp;بيا په هغه مُلک کښې جنګ وو کله چې بنى اِسرائيلو نوى معبودان خوښ کړل. د بنى اِسرائيلو په څلوېښتو زرو سړو کښې، داسې څوک نۀ وُو چې هغوئ ډال يا نېزه وړے وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6163, 'Judges 5:9', 'Judges', 5, 9, '&nbsp;زما زړۀ د بنى اِسرائيلو د مشرانو سره تړلے دے د هغه کسانو سره چې خپل ځانونه د جنګ دپاره پېش کول. د مالِک خُدائ ثناء صِفت دې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6164, 'Judges 5:10', 'Judges', 5, 10, '&nbsp;ووايئ تاسو چې په سپينو خرونو باندې سورلى کوئ، او تاسو په ښو قالينونو باندې کښېنئ، او تاسو په لاره باندې پېدل مزل کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6165, 'Judges 5:11', 'Judges', 5, 11, '&nbsp;د اوبو په ګودرو کښې د سندرغاړو آواز واورئ. هغوئ د مالِک خُدائ فتحې بيانوى، چې د بنى اِسرائيلو فتحې دى. بيا د مالِک خُدائ خلق د ښار د دروازو طرف ته روان شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6166, 'Judges 5:12', 'Judges', 5, 12, '&nbsp;پاڅه، پاڅه. دبورې، پاڅه او يوه سندره ووايه، د ابى‌نوعم زويه برقه، پاڅه، خپل قېديان روان کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6167, 'Judges 5:13', 'Judges', 5, 13, '&nbsp;بيا پاتې شوى مشران راکوز شول، د مالِک خُدائ خلق د طاقتورو خِلاف راکوز شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6168, 'Judges 5:14', 'Judges', 5, 14, '&nbsp;هغوئ د اِفرائيم نه مېدان ته راغلل، د بنيامين په قبيله او د هغوئ په خلقو پسې. مشران د مکير نه راکوز شول، او آفسران د زبولون نه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6169, 'Judges 5:15', 'Judges', 5, 15, '&nbsp;د يساکار مشران د دبورې سره راغلل، يساکار او برق هم راغلل، او هغوئ په مېدان کښې په هغۀ پسې روان وُو. خو د روبين قبيله شش او پنج کښې شوه، هغوئ دا فېصله ونۀ کړے شوه چې راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6170, 'Judges 5:16', 'Judges', 5, 16, '&nbsp;هغوئ ولې د ګډو سره وروستو پاتې شول؟ چې شپانو ته غوږ ونيسى چې رَمو ته آوازونه کوى؟ آو، د روبين قبيله شش او پنج کښې شوه، هغوئ دا فېصله ونۀ کړے شوه چې راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6171, 'Judges 5:17', 'Judges', 5, 17, '&nbsp;د جاد قبيله د اُردن نمرخاتۀ طرف ته پاتې شوه، او د دان قبيله د سمندرى جهازونو سره ولې پاتې شوه؟ د آشر قبيله د سمندر په غاړه پاتې شوه، هغوئ د سمندر په غاړه پاتې شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6172, 'Judges 5:18', 'Judges', 5, 18, '&nbsp;خو د زبولون او نفتالى خلقو خپل ژوند د جنګ مېدان په خطره کښې واچولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6173, 'Judges 5:19', 'Judges', 5, 19, '&nbsp;په تعنک کښې، د مِجدو نِهر سره، بادشاهان راغلل او هغوئ جنګ وکړو، د کنعان بادشاهانو جنګ وکړو، خو هغوئ سپين زر لوټ نۀ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6174, 'Judges 5:20', 'Judges', 5, 20, '&nbsp;د آسمان نه ستورو جګړه کوله، څنګه چې هغوئ په آسمان کښې حرکت کولو، ستورو د سِسيرا خِلاف جګړه وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6175, 'Judges 5:21', 'Judges', 5, 21, '&nbsp;په قيسون کښې يو سېلاب هغوئ يوړل د قيسون تېز درياب هغوئ په مخه کړل. زۀ به روان شم او د طاقت سره به روان يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6176, 'Judges 5:22', 'Judges', 5, 22, '&nbsp;بيا آسونه په منډه راغلل، او د خپلو پښو د سومونو نښې يې په زمکه باندې جوړې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6177, 'Judges 5:23', 'Judges', 5, 23, '&nbsp;د مالِک خُدائ فرښته فرمائى، ”د ميروز په خلقو دې لعنت وى، په هغوئ دې سخت لعنت وى. ځکه چې هغوئ د مالِک خُدائ په جنګ کښې د مدد دپاره رانۀ غلل، هغوئ د تکړه جنګ کوونکو خِلاف د مالِک خُدائ مدد ونۀ کړو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6178, 'Judges 5:24', 'Judges', 5, 24, '&nbsp;ياعيل د ټولو ښځو نه بختوره ده، چې د قينى حِبر ښځه ده، د ټولو نه بختوره ښځه چې په خېمو کښې اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6179, 'Judges 5:25', 'Judges', 5, 25, '&nbsp;سِسيراه اوبۀ وغوښتلې، خو هغې پئ ورکړل، هغې په يو ښُکلى جام کښې ورله شُملې راوړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6180, 'Judges 5:26', 'Judges', 5, 26, '&nbsp;هغې په يو لاس کښې د خېمې موږے راوړو، او په بل لاس کښې د مزدور څټک، هغې سِسيرا ووهلو او د هغۀ کوپړۍ يې ماته کړه، او تندے يې ورله سورے سورے کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6181, 'Judges 5:27', 'Judges', 5, 27, '&nbsp;د هغې په پښو کښې راپرېوتلو، وغورزېدلو او د هغې پښو کښې پروت وو. د هغې په پښو کښې لاندې پرېوتو، هغه په زمکه وغورزېدلو او مړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6182, 'Judges 5:28', 'Judges', 5, 28, '&nbsp;د سِسيرا مور د کړکۍ د جالۍ نه بهر نظر واچولو، هغې تپوس وکړو، ”د هغۀ ګاډۍ ولې دومره ناوخته کړو؟ مونږ ولې د هغۀ د ګاډۍ آواز نۀ اورو؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6183, 'Judges 5:29', 'Judges', 5, 29, '&nbsp;هوښيارو ښځو جواب ورکړو، بلکې هغې به ځان ته په خپله بيا بيا دا وئيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6184, 'Judges 5:30', 'Judges', 5, 30, '&nbsp;”هغوئ لوټ شوے مال تقسيموى، د هر فوجى دپاره يوه يا دوه ښځې، د سِسيرا دپاره به رنګ شوې جامې وى، آو، هغه ښې ګُلکارى شوې ټوکړې چې زما د غاړې دپاره دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6185, 'Judges 5:31', 'Judges', 5, 31, '&nbsp;مالِکه خُدايه، ستا ټول دشمنان دې هم داسې مړۀ شى، خو ستا دوستان دې د خپل ټول زور سره د ختونکى نمر په شان وځليږى.“ او څلوېښت کاله په هغه مُلک کښې امن وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6186, 'Judges 6:1', 'Judges', 6, 1, '&nbsp;بنى اِسرائيلو د مالِک خُدائ خِلاف بيا ګناه وکړه، نو هغۀ د ميديان خلق دې ته پرېښودل چې اووۀ کاله په هغوئ بادشاهى وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6187, 'Judges 6:2', 'Judges', 6, 2, '&nbsp;ميديانيان د بنى اِسرائيلو نه طاقتور وُو او بنى اِسرائيليان د هغوئ نه په غارونو او د غرونو په نورو محفوظو ځايونو کښې پټېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6188, 'Judges 6:3', 'Judges', 6, 3, '&nbsp;چې کله به هم بنى اِسرائيلو څۀ تخم وکَرلو، نو ميديانيان به د عماليقيانو او د صحرا د قبيلو سره راتلل او په هغوئ به يې حمله کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6189, 'Judges 6:4', 'Judges', 6, 4, '&nbsp;هغوئ به په هغه مُلک کښې خېمې ودرولې او په جنوب کښې د غزه نه ګېرچاپېره علاقې پورې فصلونه به يې تباه کول. هغوئ به ټولې ګډې، څاروى او خرونه بوتلل او بنى اِسرائيلو ته به يې د ژوند تېرولو دپاره هيڅ هم نۀ پرېښودل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6190, 'Judges 6:5', 'Judges', 6, 5, '&nbsp;هغوئ به د مُولخانو د لښکر په شان د خپلو څاروو او خېمو سره راتلل. هغوئ او د هغوئ اوښان د شمېر نه بهر وُو. هغوئ راغلل او زمکه يې ورانه ويجاړه کړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6191, 'Judges 6:6', 'Judges', 6, 6, '&nbsp;بنى اِسرائيليان د ميديانيانو په وجه بې‌وسه شول. نو بنى اِسرائيلو مالِک خُدائ ته د مدد دپاره فرياد وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6192, 'Judges 6:7', 'Judges', 6, 7, '&nbsp;کله چې بنى اِسرائيلو د ميديانيانو په وجه مالِک خُدائ ته فرياد وکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6193, 'Judges 6:8', 'Judges', 6, 8, '&nbsp;نو هغۀ د هغوئ دپاره يو پېغمبر راولېږلو او هغۀ وفرمائيل، ”ما مالِک خُدائ تاسو په مِصر کښې د غلامۍ نه راوويستلئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6194, 'Judges 6:9', 'Judges', 6, 9, '&nbsp;ما تاسو د مِصريانو نه او د هغه خلقو نه بچ کړئ چې هغوئ ستاسو سره په دې مُلک کښې جنګ وکړو. چې تاسو مخ په وړاندې تلئ نو ما هغوئ وشړل او ما تاسو له د هغوئ مُلک درکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6195, 'Judges 6:10', 'Judges', 6, 10, '&nbsp;ما تاسو ته وفرمائيل چې زۀ مالِک خُدائ ستاسو خُدائ پاک يم او تاسو به د اموريانو معبودانو عبادت نۀ کوئ د چا په مُلک کښې چې اوس تاسو اوسېږئ. خو تاسو ما ته غوږ ونۀ نيولو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6196, 'Judges 6:11', 'Judges', 6, 11, '&nbsp;بيا د مالِک خُدائ فرښته د عفره کلى ته راغله او د څېړۍ د ونې لاندې کښېناسته چې دا ونه د يوآس وه، يوآس د ابيعزر د قبيلې سړے وو. د هغۀ زوئ جدعون په پټه باندې د انګورو په لنګرۍ کښې غنم ټکول، د دې دپاره چې ميديانيان يې ونۀ ګورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6197, 'Judges 6:12', 'Judges', 6, 12, '&nbsp;د مالِک خُدائ فرښته هلته هغۀ ته راڅرګنده شوه او ورته يې وفرمائيل، ”اے تکړه او طاقتور سړيه. مالِک خُدائ ستا مل دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6198, 'Judges 6:13', 'Judges', 6, 13, '&nbsp;جدعون ورته وفرمائيل، ”صاحِبه، مالِک خُدائ چې زمونږ مل دے نو دا هر څۀ په مونږ ولې شوى دى؟ هغه ټول عجيبه کارونه چرته دى چې زمونږ پلار نيکۀ مونږ ته وئيل چې مالِک خُدائ کول، هغوئ يې څنګه د مِصر نه راوويستل؟ مالِک خُدائ مونږ پرېښودلى يُو او ميديانيانو ته يې مونږ حواله کړى يُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6199, 'Judges 6:14', 'Judges', 6, 14, '&nbsp;بيا مالِک خُدائ هغۀ له حُکم ورکړو، ”تکړه شه او ورشه او بنى اِسرائيليان د ميديانيانو نه بچ کړه. زۀ په خپله تا لېږم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(6200, 'Judges 6:15', 'Judges', 6, 15, '&nbsp;جدعون ورته په جواب کښې وفرمائيل، ”زۀ بنى اِسرائيليان څنګه خلاص کړم؟ د منسى په قبيله کښې د ټولو نه کمزورې قبيله زما ده او زۀ په خپل خاندان کښې د ټولو نه کشر يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');